from __future__ import annotations

"""Chat message model used when assembling a request to the API.

A conversation is an ordered list of these. The shapes that matter for trimming:

- a ``system`` message that pins instructions for the whole conversation,
- ``user`` / plain ``assistant`` messages,
- an ``assistant`` message carrying ``tool_calls`` (content may be null),
- ``tool`` messages that answer a specific ``tool_call_id``.

An assistant tool-call message and the tool messages that answer it are a single
exchange: the API rejects the request if they are separated or half-present.
"""

from dataclasses import dataclass, field


@dataclass(frozen=True)
class ToolCallRef:
    id: str
    name: str
    arguments: str = "{}"

    def __post_init__(self) -> None:
        if not self.id.strip():
            raise ValueError("tool call id is required")
        if not self.name.strip():
            raise ValueError("tool call name is required")


@dataclass(frozen=True)
class Message:
    role: str
    content: str | None = None
    name: str | None = None
    tool_calls: tuple[ToolCallRef, ...] = field(default_factory=tuple)
    tool_call_id: str | None = None

    def __post_init__(self) -> None:
        if self.role not in {"system", "user", "assistant", "tool"}:
            raise ValueError(f"unsupported role: {self.role}")
        if self.role == "tool" and not self.tool_call_id:
            raise ValueError("tool message requires tool_call_id")

    def is_system(self) -> bool:
        return self.role == "system"

    def is_tool_result(self) -> bool:
        return self.role == "tool"

    def has_tool_calls(self) -> bool:
        return bool(self.tool_calls)

    def tool_call_ids(self) -> list[str]:
        return [tc.id for tc in self.tool_calls]

    def to_dict(self) -> dict:
        payload: dict = {"role": self.role}
        if self.content is not None or not self.tool_calls:
            payload["content"] = self.content
        if self.name is not None:
            payload["name"] = self.name
        if self.tool_calls:
            payload["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": "function",
                    "function": {"name": tc.name, "arguments": tc.arguments},
                }
                for tc in self.tool_calls
            ]
        if self.tool_call_id is not None:
            payload["tool_call_id"] = self.tool_call_id
        return payload


def system(content: str) -> Message:
    return Message(role="system", content=content)


def user(content: str) -> Message:
    return Message(role="user", content=content)


def assistant(content: str) -> Message:
    return Message(role="assistant", content=content)


def assistant_tool_calls(calls: list[ToolCallRef], content: str | None = None) -> Message:
    return Message(role="assistant", content=content, tool_calls=tuple(calls))


def tool_result(tool_call_id: str, content: str, name: str | None = None) -> Message:
    return Message(role="tool", content=content, name=name, tool_call_id=tool_call_id)

