from __future__ import annotations

"""Local mirror of the message-sequence rules the API enforces.

If the trimmed conversation breaks one of these, the live API returns a 400.
Checking here means a broken trim fails loudly in a test instead of in prod:

- a ``tool`` message must answer an immediately preceding assistant tool-call
  group, matching one of its tool_call_ids,
- an assistant message with ``tool_calls`` must be followed by exactly one tool
  message per tool_call_id before any other role appears.
"""

from chat_messages import Message


class InvalidConversationError(ValueError):
    """Raised when a message sequence would be rejected by the API."""


def validate_message_sequence(messages: list[Message]) -> None:
    index = 0
    total = len(messages)

    while index < total:
        message = messages[index]

        if message.is_tool_result():
            raise InvalidConversationError(
                f"tool message at position {index} has no preceding tool_calls"
            )

        if message.role == "assistant" and message.has_tool_calls():
            expected_ids = message.tool_call_ids()
            replies = messages[index + 1 : index + 1 + len(expected_ids)]

            if len(replies) < len(expected_ids):
                raise InvalidConversationError(
                    f"assistant tool_calls at {index} missing tool responses"
                )
            if any(not r.is_tool_result() for r in replies):
                raise InvalidConversationError(
                    f"assistant tool_calls at {index} not directly followed by tool messages"
                )

            answered = sorted(r.tool_call_id for r in replies)
            if answered != sorted(expected_ids):
                raise InvalidConversationError(
                    f"assistant tool_calls at {index} answered by mismatched ids"
                )

            index += 1 + len(expected_ids)
            continue

        index += 1


def is_valid_sequence(messages: list[Message]) -> bool:
    try:
        validate_message_sequence(messages)
    except InvalidConversationError:
        return False
    return True


def has_system_message(messages: list[Message]) -> bool:
    return any(m.is_system() for m in messages)


def role_sequence(messages: list[Message]) -> list[str]:
    return [m.role for m in messages]


def count_tool_results(messages: list[Message]) -> int:
    return sum(1 for m in messages if m.is_tool_result())


def first_violation(messages: list[Message]) -> str | None:
    """Return the validation error message, or None if the sequence is valid."""

    try:
        validate_message_sequence(messages)
    except InvalidConversationError as exc:
        return str(exc)
    return None

