from __future__ import annotations

"""Trim conversation history so a request fits the model's context budget.

As a chat grows we cannot send everything, so older history is dropped until the
estimated token count is under budget. The newest turns matter most, so trimming
works from the front of the list.
"""

from dataclasses import dataclass

from chat_messages import Message
from token_estimator import TokenEstimator, default_estimator


@dataclass(frozen=True)
class TrimReport:
    kept: list[Message]
    dropped_count: int
    kept_tokens: int

    def kept_count(self) -> int:
        return len(self.kept)


def estimate_total(messages: list[Message], estimator: TokenEstimator | None = None) -> int:
    estimator = estimator or default_estimator()
    return estimator.estimate_messages(messages)


def is_over_budget(
    messages: list[Message],
    budget: int,
    estimator: TokenEstimator | None = None,
) -> bool:
    return estimate_total(messages, estimator) > budget


def trim_to_budget(
    messages: list[Message],
    budget: int,
    estimator: TokenEstimator | None = None,
) -> list[Message]:
    """Drop oldest messages until the conversation fits ``budget``."""

    estimator = estimator or default_estimator()
    kept = list(messages)

    while kept and estimator.estimate_messages(kept) > budget:
        kept.pop(0)

    return kept


def trim_with_report(
    messages: list[Message],
    budget: int,
    estimator: TokenEstimator | None = None,
) -> TrimReport:
    estimator = estimator or default_estimator()
    kept = trim_to_budget(messages, budget, estimator)
    return TrimReport(
        kept=kept,
        dropped_count=len(messages) - len(kept),
        kept_tokens=estimator.estimate_messages(kept),
    )


def dropped_messages(
    messages: list[Message],
    budget: int,
    estimator: TokenEstimator | None = None,
) -> list[Message]:
    kept = trim_to_budget(messages, budget, estimator)
    kept_ids = {id(m) for m in kept}
    return [m for m in messages if id(m) not in kept_ids]


def kept_roles(
    messages: list[Message],
    budget: int,
    estimator: TokenEstimator | None = None,
) -> list[str]:
    return [m.role for m in trim_to_budget(messages, budget, estimator)]

