from __future__ import annotations

"""A deterministic token estimator for chat messages.

This is not a real tokenizer; it is a stable approximation good enough to drive
budget decisions in tests and offline planning. Each message costs a small
framing overhead plus a rough character-based count of everything it carries
(content, name, and any tool-call names and arguments).
"""

import math

from chat_messages import Message


class TokenEstimator:
    def __init__(
        self,
        per_message_overhead: int = 4,
        chars_per_token: int = 4,
        reply_priming: int = 2,
    ) -> None:
        if chars_per_token < 1:
            raise ValueError("chars_per_token must be at least 1")
        self._overhead = per_message_overhead
        self._chars_per_token = chars_per_token
        self._reply_priming = reply_priming

    def _chars_to_tokens(self, text: str) -> int:
        if not text:
            return 0
        return math.ceil(len(text) / self._chars_per_token)

    def estimate_message(self, message: Message) -> int:
        tokens = self._overhead
        tokens += self._chars_to_tokens(message.content or "")
        if message.name:
            tokens += self._chars_to_tokens(message.name)
        for call in message.tool_calls:
            tokens += self._chars_to_tokens(call.name)
            tokens += self._chars_to_tokens(call.arguments)
            tokens += 3  # per-call structural overhead
        if message.tool_call_id:
            tokens += 2
        return tokens

    def estimate_messages(self, messages: list[Message]) -> int:
        if not messages:
            return 0
        total = sum(self.estimate_message(m) for m in messages)
        return total + self._reply_priming

    def fits(self, messages: list[Message], budget: int) -> bool:
        return self.estimate_messages(messages) <= budget

    def breakdown(self, messages: list[Message]) -> list[int]:
        """Per-message token estimate, in order."""

        return [self.estimate_message(m) for m in messages]

    def largest_message_tokens(self, messages: list[Message]) -> int:
        if not messages:
            return 0
        return max(self.estimate_message(m) for m in messages)

    def overage(self, messages: list[Message], budget: int) -> int:
        """How many tokens over budget a message list is (0 if it fits)."""

        return max(0, self.estimate_messages(messages) - budget)


_DEFAULT = TokenEstimator()


def default_estimator() -> TokenEstimator:
    return _DEFAULT


def estimate_messages(messages: list[Message]) -> int:
    return _DEFAULT.estimate_messages(messages)


def estimate_message(message: Message) -> int:
    return _DEFAULT.estimate_message(message)

